VALUES ('b7283e1a-b1a8-44db-a2a5-6490717191a3', '91fd81e6-f9d9-4dda-9d91-5fbc07f22f37', 'Core Lessons', 'Fire Safety lesson sequence', 'published', 0);

INSERT INTO lessons (id, module_id, title, content, status, is_visible, order_index, duration_minutes, published_at)
VALUES ('9d6ab717-6d7a-47cb-a49a-027eb864718e', 'b7283e1a-b1a8-44db-a2a5-6490717191a3', 'Fire Safety - Module Learning Outcomes', '{"schema_version":3,"title":"Fire Safety - Module Learning Outcomes","blocks":[{"id":"4310ff24-2538-4b46-bb75-3f2461ad9929","order":0,"meta":{"analyticsKey":"heading_1","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"heading","payload":{"text":"Module Learning Outcomes","level":2}},{"id":"cac30062-5bda-4bf4-b887-b81dd3e8ba0c","order":1,"meta":{"analyticsKey":"image_2","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"image","payload":{"src":"/course-assets/fire-safety/slide2_2.png","alt":"Healthcare staff reviewing fire safety training outcomes.","caption":"","width":100,"align":"center"}},{"id":"c03e5907-3c95-4b17-a162-2a58231aff26","order":2,"meta":{"analyticsKey":"paragraph_3","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"This module explains the main principles of fire safety in health and social care settings. It covers how fires start, how they spread, how to prevent them, and how staff should respond safely if a fire occurs."}},{"id":"b5ef7fcb-eb23-4805-a958-7dfda9e3a20b","order":3,"meta":{"analyticsKey":"objective_list_4","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"objective_list","payload":{"objectives":["Understand what is required to make a fire burn.","Understand smoke, toxic fumes and how fire spreads.","Recognise common workplace fire hazards.","Understand fire prevention and risk assessment responsibilities.","Know how to recognise and respond to fire safely.","Understand evacuation principles, including progressive horizontal evacuation.","Recognise basic fire safety signs, fire detectors, extinguishers and fire blankets."],"text":""}}],"metadata":{"locale":"en","readingMinutes":5,"tags":[]}}'::jsonb, 'published', true, 0, 5, NOW());

INSERT INTO lessons (id, module_id, title, content, status, is_visible, order_index, duration_minutes, published_at)
VALUES ('396a579e-2e1a-473f-9612-049390625fc9', 'b7283e1a-b1a8-44db-a2a5-6490717191a3', 'Fire Safety - Characteristics of Fire, Smoke and Toxic Fumes', '{"schema_version":3,"title":"Fire Safety - Characteristics of Fire, Smoke and Toxic Fumes","blocks":[{"id":"af321a9c-cccd-4fd4-8bb5-8b6a8fffce76","order":0,"meta":{"analyticsKey":"heading_1","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"heading","payload":{"text":"The Characteristics of Fire, Smoke and Toxic Fumes","level":2}},{"id":"354b7316-f5d2-4fe5-ae5c-c5930b57aa8d","order":1,"meta":{"analyticsKey":"image_2","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"image","payload":{"src":"/course-assets/fire-safety/slide3_1.png","alt":"Fire triangle showing heat, oxygen and fuel.","caption":"","width":100,"align":"center"}},{"id":"4811f0fb-3276-4b05-81f1-386330d367b2","order":2,"meta":{"analyticsKey":"paragraph_3","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"Fire is a rapid chemical reaction that releases heat, light and gases. To burn, a fire needs three things: heat or ignition, oxygen and fuel. These three elements are known as the fire triangle."}},{"id":"5b745087-fac2-4eab-8931-ec64aacdc93a","order":3,"meta":{"analyticsKey":"bullet_list_4","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"objective_list","payload":{"objectives":["Heat or ignition starts the fire.","Oxygen allows the fire to continue burning.","Fuel is the material that burns."],"text":""}},{"id":"02840f7b-1e69-4acb-81e6-d74c4f51e49d","order":4,"meta":{"analyticsKey":"paragraph_5","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"Removing any one part of the fire triangle can help extinguish a fire. For example, water may remove heat, a fire blanket may remove oxygen, and clearing combustible material removes fuel."}},{"id":"444916a8-73d9-42ff-a370-bfb16a2176e8","order":5,"meta":{"analyticsKey":"heading_6","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"heading","payload":{"text":"Smoke and toxic fumes","level":2}},{"id":"13d47ef8-05ae-4de7-83d3-07d2f3a1275c","order":6,"meta":{"analyticsKey":"paragraph_7","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"Smoke contains gases, vapour and tiny particles. Toxic fumes can irritate the lungs and may be especially dangerous for people with asthma, bronchitis or other respiratory conditions."}},{"id":"f53c4422-3529-4fe6-b97d-0f6ccb89e323","order":7,"meta":{"analyticsKey":"warning_box_8","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"Smoke can spread very quickly and may be more dangerous than flames. Never ignore smoke or a fire alarm."}}],"metadata":{"locale":"en","readingMinutes":5,"tags":[]}}'::jsonb, 'published', true, 1, 5, NOW());

INSERT INTO lessons (id, module_id, title, content, status, is_visible, order_index, duration_minutes, published_at)
VALUES ('d2e06e7a-b93b-4ca3-b12e-bb4c5ac7a445', 'b7283e1a-b1a8-44db-a2a5-6490717191a3', 'Fire Safety - How Fire Spreads', '{"schema_version":3,"title":"Fire Safety - How Fire Spreads","blocks":[{"id":"33f0eb15-6fee-4def-b01d-784db4f8be9b","order":0,"meta":{"analyticsKey":"heading_1","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"heading","payload":{"text":"How Fire Spreads","level":2}},{"id":"80927be1-f1be-4e33-841a-80b0c5e8dd97","order":1,"meta":{"analyticsKey":"image_2","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"image","payload":{"src":"/course-assets/fire-safety/slide2_1.png","alt":"Smoke spreading near a fire exit sign.","caption":"","width":100,"align":"center"}},{"id":"b54855c6-4d20-4bdd-86b7-a582031db1e6","order":2,"meta":{"analyticsKey":"paragraph_3","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"In the early stages of a fire, smoke can be one of the fastest spreading dangers. Fire and heat can spread in three main ways: conduction, convection and radiation."}},{"id":"a09162f9-42f2-44b9-add0-e1230509053a","order":3,"meta":{"analyticsKey":"bullet_list_4","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"objective_list","payload":{"objectives":["Conduction: heat moves through materials such as metal or pipes.","Convection: hot gases and air rise and move heat through spaces.","Radiation: heat travels through the air and can ignite nearby materials."],"text":""}},{"id":"a6a5dabd-c979-4298-b243-2069704f4b00","order":4,"meta":{"analyticsKey":"info_box_5","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"Closing doors can slow the spread of smoke and fire and may protect escape routes."}}],"metadata":{"locale":"en","readingMinutes":5,"tags":[]}}'::jsonb, 'published', true, 2, 5, NOW());

INSERT INTO lessons (id, module_id, title, content, status, is_visible, order_index, duration_minutes, published_at)
VALUES ('8d5179ab-1ef6-4c13-8c6d-89b4135eeb0f', 'b7283e1a-b1a8-44db-a2a5-6490717191a3', 'Fire Safety - Preventing Fires Starting', '{"schema_version":3,"title":"Fire Safety - Preventing Fires Starting","blocks":[{"id":"ccacd32b-31a8-413a-b86e-98ec9c8e76bf","order":0,"meta":{"analyticsKey":"heading_1","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"heading","payload":{"text":"How to Prevent Fires Starting","level":2}},{"id":"02a1afd8-b918-4d5c-82c8-096e6c368655","order":1,"meta":{"analyticsKey":"image_2","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"image","payload":{"src":"/course-assets/fire-safety/slide4_2.png","alt":"Damaged electrical appliance showing a workplace fire hazard.","caption":"","width":100,"align":"center"}},{"id":"a158db92-0b76-45ed-b138-145ebe484824","order":2,"meta":{"analyticsKey":"paragraph_3","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"The best way to avoid fire is prevention and early detection of hazards. Staff should remain alert to risks and report problems promptly."}},{"id":"bc6bbfb7-53bf-46e7-8496-7e80280410a2","order":3,"meta":{"analyticsKey":"heading_4","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"heading","payload":{"text":"Common causes of fire","level":2}},{"id":"b6b15d08-652c-4ecc-aa8f-2db7f79ee9dc","order":4,"meta":{"analyticsKey":"bullet_list_5","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"objective_list","payload":{"objectives":["Overloaded sockets or damaged electrical appliances.","Smoking or vaping in unsafe areas.","Equipment left switched on or misused.","Cooking areas left unattended.","Poor waste disposal or build-up of combustible materials.","Deliberate fire setting or arson."],"text":""}},{"id":"483d4428-77c5-46bc-b1b3-5be2fd21100d","order":5,"meta":{"analyticsKey":"warning_box_6","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"Electrical equipment should be clean, in good condition and used only as intended."}}],"metadata":{"locale":"en","readingMinutes":5,"tags":[]}}'::jsonb, 'published', true, 3, 5, NOW());

INSERT INTO lessons (id, module_id, title, content, status, is_visible, order_index, duration_minutes, published_at)
VALUES ('3c2bcaba-1c7e-4c9c-8918-188348970472', 'b7283e1a-b1a8-44db-a2a5-6490717191a3', 'Fire Safety - Preventing Fires and Risk Assessments', '{"schema_version":3,"title":"Fire Safety - Preventing Fires and Risk Assessments","blocks":[{"id":"64e42a6e-031c-4b17-83ae-c7f2167a3a6f","order":0,"meta":{"analyticsKey":"heading_1","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"heading","payload":{"text":"Preventing Fires and Risk Assessments","level":2}},{"id":"aa42f9e6-d984-4fe9-9d68-44b6b4573ffe","order":1,"meta":{"analyticsKey":"image_2","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"image","payload":{"src":"/course-assets/fire-safety/slide5_1.png","alt":"Healthcare staff discussing a fire risk assessment.","caption":"","width":100,"align":"center"}},{"id":"440398ab-f6d6-4b3b-b822-e9a3002efead","order":2,"meta":{"analyticsKey":"paragraph_3","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"Employers and employees both have responsibilities for fire safety. Fire risks should be identified, assessed and controlled before harm occurs."}},{"id":"52de3067-c322-437c-ab10-ee97dd47724c","order":3,"meta":{"analyticsKey":"heading_4","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"heading","payload":{"text":"Risk assessment steps","level":2}},{"id":"f29dc476-bcec-4295-bed5-e21e39229217","order":4,"meta":{"analyticsKey":"numbered_steps_5","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"objective_list","payload":{"objectives":["Identify significant hazards.","Decide who may be harmed and how.","Evaluate the risk and decide what controls are needed.","Record findings and communicate actions.","Review the assessment regularly or when circumstances change."],"text":""}},{"id":"b627b477-ee4b-4e9f-98e4-1d35cffffb81","order":5,"meta":{"analyticsKey":"paragraph_6","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"If you identify a potential hazard, report it and remove the risk if it is safe and appropriate to do so."}}],"metadata":{"locale":"en","readingMinutes":5,"tags":[]}}'::jsonb, 'published', true, 4, 5, NOW());

INSERT INTO lessons (id, module_id, title, content, status, is_visible, order_index, duration_minutes, published_at)
VALUES ('6212907e-e022-43ea-99ee-01c15eee237d', 'b7283e1a-b1a8-44db-a2a5-6490717191a3', 'Fire Safety - False Alarms', '{"schema_version":3,"title":"Fire Safety - False Alarms","blocks":[{"id":"1e51f0c5-c7d2-4533-855d-eca520a94ec9","order":0,"meta":{"analyticsKey":"heading_1","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"heading","payload":{"text":"False Alarms","level":2}},{"id":"43b5cd01-7772-45d2-9abd-56cf537a8d8b","order":1,"meta":{"analyticsKey":"image_2","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"image","payload":{"src":"/course-assets/fire-safety/slide14_1.png","alt":"Alarm clock dissolving into smoke to represent false alarms.","caption":"","width":100,"align":"center"}},{"id":"81c3a360-10be-4f0f-b8f1-c352f1b0932c","order":2,"meta":{"analyticsKey":"paragraph_3","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"A false alarm is the activation of an alarm for any reason other than a real fire. False alarms can waste emergency service time and disrupt normal care."}},{"id":"e625490d-a069-4be8-b0ce-5043625d27bc","order":3,"meta":{"analyticsKey":"bullet_list_4","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"objective_list","payload":{"objectives":["Smoke detector activated accidentally.","Steam, aerosols or dust affecting detectors.","Poor maintenance or testing issues.","Unsafe behaviours such as smoking in prohibited areas."],"text":""}},{"id":"b08868f9-60ff-4895-a73e-ab001b38558c","order":4,"meta":{"analyticsKey":"warning_box_5","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"Always treat an alarm as real unless authorised staff confirm otherwise."}}],"metadata":{"locale":"en","readingMinutes":5,"tags":[]}}'::jsonb, 'published', true, 5, 5, NOW());

INSERT INTO lessons (id, module_id, title, content, status, is_visible, order_index, duration_minutes, published_at)
VALUES ('f16c74b5-4715-4119-b63f-0d755f76f9df', 'b7283e1a-b1a8-44db-a2a5-6490717191a3', 'Fire Safety - Signs Related to Fire Safety', '{"schema_version":3,"title":"Fire Safety - Signs Related to Fire Safety","blocks":[{"id":"cc58390e-8f9b-47ae-a0a3-1d2810aba11f","order":0,"meta":{"analyticsKey":"heading_1","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"heading","payload":{"text":"Signs Related to Fire Safety","level":2}},{"id":"d022679e-8620-4ccf-8aca-0dd0d5412a0d","order":1,"meta":{"analyticsKey":"image_2","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"image","payload":{"src":"/course-assets/fire-safety/slide7_1.png","alt":"Fire safety signs including exit, hazard and extinguisher symbols.","caption":"","width":100,"align":"center"}},{"id":"1d192461-55d5-4318-b639-13b3959d031e","order":2,"meta":{"analyticsKey":"paragraph_3","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"Fire safety signs help staff, visitors and residents understand what to do during an emergency. Signs are commonly grouped by colour."}},{"id":"afe7bdfd-6a8d-446d-af79-50b71337cb60","order":3,"meta":{"analyticsKey":"bullet_list_4","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"objective_list","payload":{"objectives":["Green signs show safe routes or exits.","Yellow signs warn of hazards.","Red signs identify fire equipment.","Blue signs give mandatory instructions."],"text":""}},{"id":"88543278-b9c4-447f-b14b-472099bb6f40","order":4,"meta":{"analyticsKey":"info_box_5","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"Staff should know where fire exits, alarm points and firefighting equipment are located in their workplace."}}],"metadata":{"locale":"en","readingMinutes":5,"tags":[]}}'::jsonb, 'published', true, 6, 5, NOW());

INSERT INTO lessons (id, module_id, title, content, status, is_visible, order_index, duration_minutes, published_at)
VALUES ('4cec119c-c8c8-4455-b108-a95743c9e71e', 'b7283e1a-b1a8-44db-a2a5-6490717191a3', 'Fire Safety - How to Recognise a Fire', '{"schema_version":3,"title":"Fire Safety - How to Recognise a Fire","blocks":[{"id":"6b55ee17-374e-4e7b-ab51-05e35e728737","order":0,"meta":{"analyticsKey":"heading_1","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"heading","payload":{"text":"How to Recognise a Fire","level":2}},{"id":"a50619bf-6f6f-4708-8015-f172f725ba26","order":1,"meta":{"analyticsKey":"image_2","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"image","payload":{"src":"/course-assets/fire-safety/slide8_1.png","alt":"Four senses used to detect fire: hearing, smell, touch and vision.","caption":"","width":100,"align":"center"}},{"id":"8c453604-ccd7-44ac-a60a-088d5a403bcc","order":2,"meta":{"analyticsKey":"paragraph_3","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"The senses can help staff recognise a fire in the early stages. Early recognition allows faster action and can reduce harm."}},{"id":"4ea72c54-c633-4856-b024-1e906008b7db","order":3,"meta":{"analyticsKey":"bullet_list_4","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"objective_list","payload":{"objectives":["Hearing: flames may roar or crackle and alarms may sound.","Smell: smoke, gas or burning materials may be noticeable.","Touch: heat may be felt through doors, walls or handles.","Vision: smoke, flames or unusual haze may be seen."],"text":""}},{"id":"a2b2fff8-11e9-4676-9225-673ad25d085b","order":4,"meta":{"analyticsKey":"warning_box_5","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"Never open a door if you suspect fire is behind it. Check for heat and follow local emergency procedures."}}],"metadata":{"locale":"en","readingMinutes":5,"tags":[]}}'::jsonb, 'published', true, 7, 5, NOW());

INSERT INTO lessons (id, module_id, title, content, status, is_visible, order_index, duration_minutes, published_at)
VALUES ('2adb7a40-5f7d-48aa-9f6e-e7555556a9f9', 'b7283e1a-b1a8-44db-a2a5-6490717191a3', 'Fire Safety - The Five Steps of Fire Response', '{"schema_version":3,"title":"Fire Safety - The Five Steps of Fire Response","blocks":[{"id":"75c1aeb7-5d61-4152-a96d-75944d0a2a77","order":0,"meta":{"analyticsKey":"heading_1","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"heading","payload":{"text":"The Five Steps of Fire Response","level":2}},{"id":"8ec2873b-b12c-47b3-b31f-aa5f90ab2307","order":1,"meta":{"analyticsKey":"image_2","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"image","payload":{"src":"/course-assets/fire-safety/slide6_1.png","alt":"Fire engine arriving during an emergency response.","caption":"","width":100,"align":"center"}},{"id":"94fff2ae-1182-4d5d-9dfa-71bd3b8e4fc1","order":2,"meta":{"analyticsKey":"numbered_steps_3","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"objective_list","payload":{"objectives":["Raise the alarm.","Call the fire service according to local policy.","Tackle the fire only if trained, safe and appropriate.","Evacuate according to the workplace plan.","Meet the fire service and provide clear information."],"text":""}},{"id":"a221736a-ddfc-47b8-8d93-2b5ea1bf68b2","order":3,"meta":{"analyticsKey":"paragraph_4","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"Your first responsibility is to protect life. Do not attempt to fight a fire unless you are trained, the fire is small, and you have a clear escape route."}}],"metadata":{"locale":"en","readingMinutes":5,"tags":[]}}'::jsonb, 'published', true, 8, 5, NOW());

INSERT INTO lessons (id, module_id, title, content, status, is_visible, order_index, duration_minutes, published_at)
VALUES ('d33a04c7-e7c7-4f39-bffe-fd8501ba592a', 'b7283e1a-b1a8-44db-a2a5-6490717191a3', 'Fire Safety - How to Ensure Residents are Safe', '{"schema_version":3,"title":"Fire Safety - How to Ensure Residents are Safe","blocks":[{"id":"3fc861f3-19b3-461c-a03c-2a91ce67536e","order":0,"meta":{"analyticsKey":"heading_1","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"heading","payload":{"text":"How to Ensure Residents are Safe","level":2}},{"id":"941e04ad-d16d-437c-a1d8-1336fb82347c","order":1,"meta":{"analyticsKey":"image_2","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"image","payload":{"src":"/course-assets/fire-safety/slide9_1.png","alt":"Older resident in a bed representing dependency during evacuation.","caption":"","width":100,"align":"center"}},{"id":"7b8e5561-8830-43a2-9eed-8f0960e8dbb0","order":2,"meta":{"analyticsKey":"paragraph_3","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"In care settings, some residents may need support during evacuation because of mobility, cognition, illness or dependency. Staff should know who may need help and where their emergency information is kept."}},{"id":"2c4192b2-7891-4364-8bbe-b95a16cb8513","order":3,"meta":{"analyticsKey":"bullet_list_4","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"objective_list","payload":{"objectives":["Independent residents may be able to walk unaided but still need direction.","Dependent residents may need mobility aids or staff support.","Highly dependent residents may need evacuation using beds, chairs or specialist equipment."],"text":""}},{"id":"b3761dea-52ba-4f7f-a7ac-94f8b6ab6fc6","order":4,"meta":{"analyticsKey":"info_box_5","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"Personal Emergency Evacuation Plans should be available for residents who require additional support."}}],"metadata":{"locale":"en","readingMinutes":5,"tags":[]}}'::jsonb, 'published', true, 9, 5, NOW());

INSERT INTO lessons (id, module_id, title, content, status, is_visible, order_index, duration_minutes, published_at)
VALUES ('06fc58dc-1add-47de-a93a-fb5fd5c35e82', 'b7283e1a-b1a8-44db-a2a5-6490717191a3', 'Fire Safety - Progressive Horizontal Evacuation', '{"schema_version":3,"title":"Fire Safety - Progressive Horizontal Evacuation","blocks":[{"id":"6dd5ea94-7bf7-4992-b177-399467c08d49","order":0,"meta":{"analyticsKey":"heading_1","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"heading","payload":{"text":"Progressive Horizontal Evacuation","level":2}},{"id":"8eaf034d-0d81-4321-a1fe-da2a95729aaf","order":1,"meta":{"analyticsKey":"image_2","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"image","payload":{"src":"/course-assets/fire-safety/slide10_1.png","alt":"Healthcare staff moving a hospital bed along a corridor during evacuation practice.","caption":"","width":100,"align":"center"}},{"id":"d8e1b358-ab08-454e-b314-abf4727bf031","order":2,"meta":{"analyticsKey":"paragraph_3","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"Progressive horizontal evacuation involves moving residents or patients through fire doors on the same level to an area of relative safety. This is commonly used in larger care buildings."}},{"id":"1b41a7c7-4d75-45c2-a51c-2900bef4e4a2","order":3,"meta":{"analyticsKey":"bullet_list_4","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"objective_list","payload":{"objectives":["Check the fire panel if safe and authorised.","Move people away from smoke or fire.","Close doors and fire doors behind you.","Move residents through fire doors to the next safe area.","Only move downstairs if there is no safe area on the same level."],"text":""}},{"id":"511aadb3-a7c3-40dd-9105-66dbe2dd7e84","order":4,"meta":{"analyticsKey":"warning_box_5","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"If the alarm is intermittent, stay alert and stop non-essential activity near the affected area."}}],"metadata":{"locale":"en","readingMinutes":5,"tags":[]}}'::jsonb, 'published', true, 10, 5, NOW());

INSERT INTO lessons (id, module_id, title, content, status, is_visible, order_index, duration_minutes, published_at)
VALUES ('473016f3-8876-44d0-a373-6ac12bc0a60b', 'b7283e1a-b1a8-44db-a2a5-6490717191a3', 'Fire Safety - Fire Detectors', '{"schema_version":3,"title":"Fire Safety - Fire Detectors","blocks":[{"id":"a54e7d57-3008-499d-abe9-849e2c0e9f75","order":0,"meta":{"analyticsKey":"heading_1","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"heading","payload":{"text":"Fire Detectors","level":2}},{"id":"2e4fba78-0c3e-45ff-a837-688d5aae97c7","order":1,"meta":{"analyticsKey":"image_2","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"image","payload":{"src":"/course-assets/fire-safety/slide8_2.png","alt":"Manual fire alarm call point.","caption":"","width":100,"align":"center"}},{"id":"2a4fb83e-dfac-4e3a-9f19-1be7afdfe96f","order":2,"meta":{"analyticsKey":"paragraph_3","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"Fire detection systems warn people that there may be a fire. Some systems alert emergency services automatically, while others require staff to call them manually."}},{"id":"b09ec367-7dfc-40e5-9b89-853cacb08bb7","order":3,"meta":{"analyticsKey":"bullet_list_4","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"objective_list","payload":{"objectives":["Smoke detectors identify smoke particles.","Heat detectors identify rising temperature.","Manual call points allow staff to raise the alarm when fire is discovered."],"text":""}},{"id":"37ba96a5-41fd-4f70-be77-d064bbdee643","order":4,"meta":{"analyticsKey":"info_box_5","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"Staff must know how their local fire alarm system works and who to contact in an emergency."}}],"metadata":{"locale":"en","readingMinutes":5,"tags":[]}}'::jsonb, 'published', true, 11, 5, NOW());

INSERT INTO lessons (id, module_id, title, content, status, is_visible, order_index, duration_minutes, published_at)
VALUES ('b9202099-62bf-4e51-b99f-e7b6d83cd475', 'b7283e1a-b1a8-44db-a2a5-6490717191a3', 'Fire Safety - Fire Extinguishers', '{"schema_version":3,"title":"Fire Safety - Fire Extinguishers","blocks":[{"id":"f27ee2b0-423f-489c-9036-d16929c507db","order":0,"meta":{"analyticsKey":"heading_1","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"heading","payload":{"text":"Fire Extinguishers","level":2}},{"id":"db4e4b0d-7400-49a9-93b1-49d921066d35","order":1,"meta":{"analyticsKey":"image_2","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"image","payload":{"src":"/course-assets/fire-safety/slide13_1.png","alt":"Different types of fire extinguishers and fire safety labels.","caption":"","width":100,"align":"center"}},{"id":"5c687575-98ff-4b18-a237-fd5c4d3d7930","order":2,"meta":{"analyticsKey":"paragraph_3","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"Different extinguishers are used for different types of fire. Using the wrong extinguisher can be dangerous and may make the fire worse."}},{"id":"b74ce4e6-897f-4e76-bd99-98d3a33b0a56","order":3,"meta":{"analyticsKey":"bullet_list_4","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"objective_list","payload":{"objectives":["Water extinguishers are commonly used for solid combustible materials.","Foam may be used for some liquid fires.","CO2 extinguishers may be used for some electrical fires.","Dry powder may be used in specific circumstances but can reduce visibility and affect breathing."],"text":""}},{"id":"7fd0c75e-2148-453d-a70b-c9d0c0cdb036","order":4,"meta":{"analyticsKey":"warning_box_5","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"Only use an extinguisher if you have been trained, it is safe to do so, and you have a clear escape route."}}],"metadata":{"locale":"en","readingMinutes":5,"tags":[]}}'::jsonb, 'published', true, 12, 5, NOW());

INSERT INTO lessons (id, module_id, title, content, status, is_visible, order_index, duration_minutes, published_at)
VALUES ('1ff5edbd-d73a-4ff7-aec8-51ea7d1f3aa6', 'b7283e1a-b1a8-44db-a2a5-6490717191a3', 'Fire Safety - Fire Blankets', '{"schema_version":3,"title":"Fire Safety - Fire Blankets","blocks":[{"id":"b0abf597-e653-43d3-891f-7ae2582d73ad","order":0,"meta":{"analyticsKey":"heading_1","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"heading","payload":{"text":"Fire Blankets","level":2}},{"id":"7d461064-a6a1-45b7-a7b3-bb611586f07e","order":1,"meta":{"analyticsKey":"image_2","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"image","payload":{"src":"/course-assets/fire-safety/slide13_2.png","alt":"Fire blanket mounted in a kitchen area.","caption":"","width":100,"align":"center"}},{"id":"76c72a78-fa4a-4dd9-a303-56a82c71d631","order":2,"meta":{"analyticsKey":"paragraph_3","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"Fire blankets are used to smother small fires by removing oxygen. They are commonly found in kitchen areas and may be useful for small pan fires or clothing fires when used correctly."}},{"id":"87d78637-5599-4b16-b885-3f993107f783","order":3,"meta":{"analyticsKey":"numbered_steps_4","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"objective_list","payload":{"objectives":["Pull the tabs to release the blanket.","Hold the blanket in front of you to protect your hands.","Place the blanket over the fire without throwing it.","Leave it in place until the fire is completely cool."],"text":""}},{"id":"2e96a1db-3d66-4614-a08d-a62a4411c203","order":4,"meta":{"analyticsKey":"warning_box_5","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"Never take unnecessary risks. If the fire is spreading, raise the alarm and evacuate."}}],"metadata":{"locale":"en","readingMinutes":5,"tags":[]}}'::jsonb, 'published', true, 13, 5, NOW());

INSERT INTO lessons (id, module_id, title, content, status, is_visible, order_index, duration_minutes, published_at)
VALUES ('36bf8e39-50b0-4634-8fc4-a1fda7aa2c46', 'b7283e1a-b1a8-44db-a2a5-6490717191a3', 'Fire Safety - Summary', '{"schema_version":3,"title":"Fire Safety - Summary","blocks":[{"id":"b7485e50-b22b-496c-b21e-80695c3ceffe","order":0,"meta":{"analyticsKey":"heading_1","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"heading","payload":{"text":"Summary","level":2}},{"id":"b50a438a-6962-4b74-aff5-ae2b69fd5b9b","order":1,"meta":{"analyticsKey":"image_2","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"image","payload":{"src":"/course-assets/fire-safety/slide11_1.png","alt":"Healthcare staff reviewing fire safety procedures together.","caption":"","width":100,"align":"center"}},{"id":"df89e063-b15f-4504-b064-604b31f28308","order":2,"meta":{"analyticsKey":"bullet_list_3","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"objective_list","payload":{"objectives":["Fire requires heat, oxygen and fuel.","Smoke and toxic fumes can spread quickly and harm people.","Fire prevention depends on hazard awareness, safe working practices and reporting risks.","Fire risk assessments identify hazards and control measures.","Fire alarms must always be treated seriously.","Staff should know how to raise the alarm, evacuate and support residents safely.","Fire safety equipment should only be used by trained staff when safe and appropriate."],"text":""}}],"metadata":{"locale":"en","readingMinutes":5,"tags":[]}}'::jsonb, 'published', true, 14, 5, NOW());

INSERT INTO lessons (id, module_id, title, content, status, is_visible, order_index, duration_minutes, published_at)
VALUES ('4c363d63-4d08-4f30-b052-45b72e1e4f08', 'b7283e1a-b1a8-44db-a2a5-6490717191a3', 'Fire Safety - A Chance to Reflect', '{"schema_version":3,"title":"Fire Safety - A Chance to Reflect","blocks":[{"id":"7f2bc35f-78fa-49f0-b3b7-cbd7644905cf","order":0,"meta":{"analyticsKey":"heading_1","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"heading","payload":{"text":"A Chance to Reflect","level":2}},{"id":"e4b18e31-c1e3-4ae1-a7e1-7f0842b58216","order":1,"meta":{"analyticsKey":"image_2","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"image","payload":{"src":"/course-assets/fire-safety/slide1_1.png","alt":"Healthcare worker reflecting on fire safety responsibilities.","caption":"","width":100,"align":"center"}},{"id":"acac9064-9f37-4804-9ed2-ecedd3d965df","order":2,"meta":{"analyticsKey":"paragraph_3","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"Take a moment to reflect on how fire safety applies to your workplace and your role."}},{"id":"3b8c8ade-457e-407b-a588-945b4ac44dfa","order":3,"meta":{"analyticsKey":"bullet_list_4","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"objective_list","payload":{"objectives":["Where are the nearest fire exits in your workplace?","Do you know how to raise the alarm?","Do you know which residents need support to evacuate?","Where is the fire assembly point?","Who should you report fire hazards to?"],"text":""}}],"metadata":{"locale":"en","readingMinutes":5,"tags":[]}}'::jsonb, 'published', true, 15, 5, NOW());

INSERT INTO lessons (id, module_id, title, content, status, is_visible, order_index, duration_minutes, published_at)
VALUES ('c9250121-b60a-415e-bce3-a1ee6ab2aa2a', 'b7283e1a-b1a8-44db-a2a5-6490717191a3', 'Fire Safety - References', '{"schema_version":3,"title":"Fire Safety - References","blocks":[{"id":"df5f36fd-6efa-4c0e-bb71-ae1be1899669","order":0,"meta":{"analyticsKey":"heading_1","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"heading","payload":{"text":"References","level":2}},{"id":"83c9f2d4-278c-4f5d-b3e5-c34ec0857a8d","order":1,"meta":{"analyticsKey":"image_2","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"image","payload":{"src":"/course-assets/fire-safety/slide12_1.png","alt":"Fire safety guidance documents and workplace policy folder.","caption":"","width":100,"align":"center"}},{"id":"9d9dc4a4-7b6c-4323-81d7-9cb4b6a86f26","order":2,"meta":{"analyticsKey":"paragraph_3","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"rich_text","payload":{"text":"This module is informed by standard UK fire safety principles and workplace fire safety responsibilities."}},{"id":"1d5a056b-85a5-446e-afc1-dcec5a97ab49","order":3,"meta":{"analyticsKey":"bullet_list_4","tags":[],"aiHints":{"semanticRole":"","summary":"","difficulty":""}},"type":"objective_list","payload":{"objectives":["Regulatory Reform Fire Safety Order 2005.","Fire Safety Act 2021.","Fire Safety Bill 2020 guidance.","Health and Safety Executive fire safety guidance.","Local organisational fire safety policies and procedures."],"text":""}}],"metadata":{"locale":"en","readingMinutes":5,"tags":[]}}'::jsonb, 'published', true, 16, 5, NOW());

